insert into public.recipe_ingredients (
  recipe_id,
  ingredient_key,
  role_key,
  necessity_key,
  is_minimum_required,
  quantity_text,
  quantity_value,
  unit_key,
  sort_order,
  note
)
select
  recipes.id,
  ingredient_rows.ingredient_key,
  ingredient_rows.role_key,
  ingredient_rows.necessity_key,
  ingredient_rows.is_minimum_required,
  ingredient_rows.quantity_text,
  ingredient_rows.quantity_value,
  ingredient_rows.unit_key,
  ingredient_rows.sort_order,
  ingredient_rows.note
from ingredient_rows
join public.recipes on recipes.recipe_key = ingredient_rows.recipe_key;

