insert into public.recipe_tools (
  recipe_id,
  equipment_key,
  necessity_key,
  sort_order,
  note
)
select
  recipes.id,
  tool_rows.equipment_key,
  tool_rows.necessity_key,
  tool_rows.sort_order,
  tool_rows.note
from tool_rows
join public.recipes on recipes.recipe_key = tool_rows.recipe_key;

