insert into public.recipe_substitutions (
  recipe_id,
  ingredient_key,
  substitute_ingredient_key,
  quality_impact,
  note
)
select
  recipes.id,
  substitution_rows.ingredient_key,
  substitution_rows.substitute_ingredient_key,
  substitution_rows.quality_impact,
  substitution_rows.note
from substitution_rows
join public.recipes on recipes.recipe_key = substitution_rows.recipe_key;

with step_rows (
  recipe_key,
  step_number,
  title,
  body,
  estimated_minutes,
  timer_seconds,
  image_url,
  ingredient_keys,
  equipment_keys,
  tips
) as (
  values
  ('tomato_egg_stir_fry', 1, '准备食材', '处理 番茄、鸡蛋、小葱、大蒜，需要切块的食材切成一口大小；调料先放在手边。', 4, null, null, array['tomato', 'egg', 'scallion', 'garlic']::text[], array['knife', 'cutting_board']::text[], null),
  ('tomato_egg_stir_fry', 2, '完成主要烹饪', '热锅加油，先下蛋白质或不易熟的食材，再加入蔬菜翻炒；用 盐、烹饪油、糖 调味。', 8, null, null, array['tomato', 'egg']::text[], array['stove_or_hotplate', 'frying_pan_or_wok', 'spatula']::text[], null),
  ('tomato_egg_stir_fry', 3, '调味与装盘', '尝味后按口味微调，装盘时把颜色最鲜明的食材放在表面，让成品更清爽。', 3, null, null, array['salt', 'cooking_oil', 'sugar', 'scallion', 'garlic']::text[], array['plate']::text[], null),
  ('scallion_egg_fried_rice', 1, '准备食材', '处理 大米、鸡蛋、小葱、豌豆、胡萝卜，需要切块的食材切成一口大小；调料先放在手边。', 4, null, null, array['rice', 'egg', 'scallion', 'peas', 'carrot']::text[], array['bowl']::text[], null),
  ('scallion_egg_fried_rice', 2, '完成主要烹饪', '米饭打散后入锅，先炒香蛋白质和蔬菜，再加入米饭翻到粒粒分开；用 烹饪油、盐、酱油 调味。', 8, null, null, array['rice', 'egg', 'scallion']::text[], array['stove_or_hotplate', 'frying_pan_or_wok', 'spatula', 'bowl']::text[], null),
