insert into public.recipe_steps (
  recipe_id,
  step_number,
  title,
  body,
  estimated_minutes,
  timer_seconds,
  image_url,
  ingredient_keys,
  equipment_keys,
  tips
)
select
  recipes.id,
  step_rows.step_number,
  step_rows.title,
  step_rows.body,
  step_rows.estimated_minutes,
  step_rows.timer_seconds,
  step_rows.image_url,
  step_rows.ingredient_keys,
  step_rows.equipment_keys,
  step_rows.tips
from step_rows
join public.recipes on recipes.recipe_key = step_rows.recipe_key;

commit;
